sys_script_client.script:
function onSubmit() {

    /*
     * ============================================================
     * CARESYNC 360 - WARD MASTER CLIENT VALIDATION
     * ============================================================
     *
     * Purpose:
     * Validate Ward data before INSERT or UPDATE.
     *
     * Important:
     * Returning false prevents the form from being submitted.
     * Therefore invalid records are NOT saved.
     */

    var wardName = (g_form.getValue('ward_name') || '').trim();
    var wardCode = (g_form.getValue('ward_code') || '').trim();
    var department = (g_form.getValue('department') || '').trim();
    var wardType = (g_form.getValue('ward_type') || '').trim();

    var capacityValue = (g_form.getValue('capacity') || '').trim();
    var floorValue = (g_form.getValue('floor') || '').trim();


    /*
     * ------------------------------------------------------------
     * 1. Ward Name validation
     * ------------------------------------------------------------
     */

    if (!wardName) {

        g_form.showFieldMsg(
            'ward_name',
            'Ward Name is required.',
            'error'
        );

        return false;
    }


    /*
     * Ward Name should not be only spaces.
     */

    if (wardName.length < 2) {

        g_form.showFieldMsg(
            'ward_name',
            'Ward Name must contain at least 2 characters.',
            'error'
        );

        return false;
    }


    /*
     * ------------------------------------------------------------
     * 2. Ward Code validation
     * ------------------------------------------------------------
     */

    if (!wardCode) {

        g_form.showFieldMsg(
            'ward_code',
            'Ward Code is required.',
            'error'
        );

        return false;
    }


    /*
     * Ward Code:
     * Allow letters, numbers, hyphen and underscore.
     */

    var wardCodePattern = /^[A-Za-z0-9_-]+$/;

    if (!wardCodePattern.test(wardCode)) {

        g_form.showFieldMsg(
            'ward_code',
            'Ward Code may contain only letters, numbers, hyphens, and underscores.',
            'error'
        );

        return false;
    }


    /*
     * ------------------------------------------------------------
     * 3. Department validation
     * ------------------------------------------------------------
     */

    if (!department) {

        g_form.showFieldMsg(
            'department',
            'Department is required.',
            'error'
        );

        return false;
    }


    /*
     * ------------------------------------------------------------
     * 4. Ward Type validation
     * ------------------------------------------------------------
     */

    if (!wardType) {

        g_form.showFieldMsg(
            'ward_type',
            'Please select a Ward Type.',
            'error'
        );

        return false;
    }


    /*
     * ------------------------------------------------------------
     * 5. Capacity validation
     * ------------------------------------------------------------
     *
     * Capacity is optional.
     *
     * If supplied:
     * - Must be a whole number
     * - Cannot be negative
     */

    if (capacityValue !== '') {

        if (!/^\d+$/.test(capacityValue)) {

            g_form.showFieldMsg(
                'capacity',
                'Capacity must be a whole number.',
                'error'
            );

            return false;
        }

        var capacity = parseInt(capacityValue, 10);

        if (capacity < 0) {

            g_form.showFieldMsg(
                'capacity',
                'Capacity cannot be negative.',
                'error'
            );

            return false;
        }
    }


    /*
     * ------------------------------------------------------------
     * 6. Floor validation
     * ------------------------------------------------------------
     *
     * Floor is optional.
     *
     * If supplied:
     * - Must be a whole number
     * - Cannot be negative
     */

    if (floorValue !== '') {

        if (!/^\d+$/.test(floorValue)) {

            g_form.showFieldMsg(
                'floor',
                'Floor must be a whole number.',
                'error'
            );

            return false;
        }

        var floor = parseInt(floorValue, 10);

        if (floor < 0) {

            g_form.showFieldMsg(
                'floor',
                'Floor cannot be negative.',
                'error'
            );

            return false;
        }
    }


    /*
     * ------------------------------------------------------------
     * 7. Final validation result
     * ------------------------------------------------------------
     *
     * If execution reaches this point, all validations passed.
     *
     * Returning true allows:
     * - Insert
     * - Update
     */

    return true;
}
